import java.util.HashMap;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        HashMap<String, Integer> stock = new HashMap<>();
        while (n-- > 0) {
            String op = sc.next();
            String sku = sc.next();
            int qty = sc.nextInt();
            if (op.equals("RECEIVE")) {
                if (stock.containsKey(sku)) {
                    int updated = stock.get(sku) + qty;
                    stock.put(sku, updated);
                    System.out.println(sku + " restocked to " + updated);
                } else {
                    stock.put(sku, qty);
                    System.out.println(sku + " registered with " + qty);
                }
            } else if (op.equals("SHIP")) {
                if (stock.containsKey(sku) && stock.get(sku) >= qty) {
                    int left = stock.get(sku) - qty;
                    stock.put(sku, left);
                    System.out.println(sku + " shipped, remaining " + left);
                } else {
                    System.out.println(sku + " shipment denied");
                }
            }
        }
        System.out.println("SKUs: " + stock.size());
    }
}

