import java.util.ArrayList;
import java.util.Comparator;
import java.util.Scanner;
import java.util.TreeMap;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        TreeMap<String, Integer> scores = new TreeMap<>();
        for (int i = 0; i < n; i++) {
            scores.put(sc.next(), sc.nextInt());
        }
        int k = sc.nextInt();
        ArrayList<String> names = new ArrayList<>(scores.keySet());
        names.sort(new Comparator<String>() {
            public int compare(String a, String b) {
                int sa = scores.get(a);
                int sb = scores.get(b);
                if (sa != sb) return sb - sa;
                return a.compareTo(b);
            }
        });
        for (int i = 0; i < k; i++) {
            String name = names.get(i);
            System.out.println(name + " " + scores.get(name));
        }
    }
}

import java.util.HashMap;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] ids = new int[n];
        HashMap<Integer, Integer> count = new HashMap<>();
        for (int i = 0; i < n; i++) {
            ids[i] = sc.nextInt();
            Integer seen = count.get(ids[i]);
            if (seen == null) count.put(ids[i], 1);
            else count.put(ids[i], seen + 1);
        }
        int first = -1;
        for (int i = 0; i < n; i++) {
            if (count.get(ids[i]) == 1) {
                first = ids[i];
                break;
            }
        }
        int uniques = 0;
        for (Integer key : count.keySet()) {
            if (count.get(key) == 1) uniques++;
        }
        System.out.println(first);
        System.out.println(uniques);
    }
}

import java.util.Comparator;
import java.util.PriorityQueue;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        PriorityQueue<int[]> pq = new PriorityQueue<>(new Comparator<int[]>() {
            public int compare(int[] a, int[] b) {
                if (a[1] != b[1]) return a[1] - b[1];
                return a[0] - b[0];
            }
        });
        for (int i = 0; i < n; i++) {
            int id = sc.nextInt();
            int pr = sc.nextInt();
            pq.add(new int[] { id, pr });
        }
        int threshold = sc.nextInt();
        int deferred = 0;
        while (!pq.isEmpty()) {
            int[] job = pq.poll();
            if (job[1] <= threshold) {
                System.out.println(job[0] + " " + job[1]);
            } else {
                deferred++;
            }
        }
        System.out.println("Deferred: " + deferred);
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String word = sc.next();
        HashMap<Character, Integer> freq = new HashMap<>();
        for (int i = 0; i < word.length(); i++) {
            char c = word.charAt(i);
            Integer cur = freq.get(c);
            if (cur == null) freq.put(c, 1);
            else freq.put(c, cur + 1);
        }
        ArrayList<Character> keys = new ArrayList<>(freq.keySet());
        Collections.sort(keys, new Comparator<Character>() {
            public int compare(Character a, Character b) {
                int ca = freq.get(a);
                int cb = freq.get(b);
                if (ca != cb) return cb - ca;
                return a.charValue() - b.charValue();
            }
        });
        for (char c : keys) {
            System.out.println(c + " " + freq.get(c));
        }
    }
}

