import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        HashMap<String, Integer> votes = new HashMap<>();
        for (int i = 0; i < n; i++) {
            String name = sc.next();
            Integer cur = votes.get(name);
            if (cur == null) votes.put(name, 1);
            else votes.put(name, cur + 1);
        }
        int q = sc.nextInt();
        while (q-- > 0) {
            String op = sc.next();
            if (op.equals("VOTES")) {
                String name = sc.next();
                if (votes.containsKey(name)) System.out.println(votes.get(name));
                else System.out.println(0);
            } else if (op.equals("WINNER")) {
                ArrayList<String> names = new ArrayList<>(votes.keySet());
                Collections.sort(names);
                String best = names.get(0);
                for (String name : names) {
                    if (votes.get(name) > votes.get(best)) best = name;
                }
                System.out.println(best + " " + votes.get(best));
            }
        }
    }
}
